const vars = typeof $vars !== 'undefined' ? $vars : {};
const env = typeof $env !== 'undefined' ? $env : {};
const readConfig = (name) => vars[name] || env[name];

const SUPABASE_URL = readConfig('SUPABASE_URL');
const SUPABASE_SERVICE_ROLE_KEY = readConfig('SUPABASE_SERVICE_ROLE_KEY');
const TELEGRAM_BOT_TOKEN = readConfig('TELEGRAM_BOT_TOKEN');

const chatByAudience = {
  admin: readConfig('TELEGRAM_CHAT_ADMIN'),
  manager: readConfig('TELEGRAM_CHAT_MANAGER') || readConfig('TELEGRAM_CHAT_ADMIN'),
  dispatcher: readConfig('TELEGRAM_CHAT_DISPATCHER') || readConfig('TELEGRAM_CHAT_ADMIN'),
  sale: readConfig('TELEGRAM_CHAT_SALE') || readConfig('TELEGRAM_CHAT_ADMIN'),
  accountant: readConfig('TELEGRAM_CHAT_ACCOUNTANT') || readConfig('TELEGRAM_CHAT_ADMIN'),
  driver: readConfig('TELEGRAM_CHAT_DRIVER') || readConfig('TELEGRAM_CHAT_ADMIN')
};

function assertEnv(name, value) {
  if (!value) throw new Error(`Missing n8n env: ${name}`);
}

assertEnv('SUPABASE_URL', SUPABASE_URL);
assertEnv('SUPABASE_SERVICE_ROLE_KEY', SUPABASE_SERVICE_ROLE_KEY);
assertEnv('TELEGRAM_BOT_TOKEN', TELEGRAM_BOT_TOKEN);
assertEnv('TELEGRAM_CHAT_ADMIN', chatByAudience.admin);

const supabaseHeaders = {
  apikey: SUPABASE_SERVICE_ROLE_KEY,
  Authorization: `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
  'Content-Type': 'application/json'
};

const httpRequest = this.helpers.httpRequest.bind(this.helpers);

async function supabaseRpc(name, body) {
  try {
    return await httpRequest({
      method: 'POST',
      url: `${SUPABASE_URL}/rest/v1/rpc/${name}`,
      headers: supabaseHeaders,
      body,
      json: true
    });
  } catch (error) {
    throw new Error(`${name} failed: ${error.message}`);
  }
}

function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

function money(value) {
  const number = Number(value || 0);
  return number > 0 ? new Intl.NumberFormat('vi-VN').format(number) + ' đ' : '';
}

function formatDateTime(value) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return new Intl.DateTimeFormat('vi-VN', {
    timeZone: 'Asia/Ho_Chi_Minh',
    hour: '2-digit',
    minute: '2-digit',
    day: '2-digit',
    month: '2-digit'
  }).format(date);
}

async function getOrder(event) {
  const orderId = event.entity_id || event.payload?.entityId;
  if (!orderId) return null;
  try {
    const select = [
      'id', 'code', 'customer_name', 'customer_phone', 'pickup', 'dropoff',
      'service_label', 'start_at', 'end_at', 'amount_due', 'driver_cost',
      'vehicle_id', 'driver_id', 'driver_full_name', 'driver_phone',
      'external_vehicle_plate_no', 'external_driver_name', 'external_driver_phone',
      'dispatch_status', 'order_status', 'payment_status', 'invoice_status',
      'driver_collected_amount', 'driver_expense_fuel', 'driver_expense_toll',
      'driver_expense_parking', 'driver_expense_water', 'driver_expense_other'
    ].join(',');
    const rows = await httpRequest({
      method: 'GET',
      url: `${SUPABASE_URL}/rest/v1/app_dispatch_orders?select=${encodeURIComponent(select)}&id=eq.${encodeURIComponent(orderId)}&limit=1`,
      headers: supabaseHeaders,
      json: true
    });
    return Array.isArray(rows) && rows.length > 0 ? rows[0] : null;
  } catch (error) {
    return null;
  }
}

function actionFor(eventType, audience) {
  const key = eventType || '';
  const actions = {
    dispatch_proposal_submitted: 'Điều hành kiểm tra thông tin, sau đó duyệt hoặc từ chối đề xuất.',
    urgent_driver_proposal_submitted: 'Điều hành xử lý gấp: gọi xác nhận, duyệt nhanh nếu đủ điều kiện chạy.',
    urgent_driver_proposal_needs_sales_completion: 'Sale bổ sung phần thương mại: giá bán, nguồn khách, hóa đơn và điều khoản thanh toán.',
    driver_proposal_submitted: 'Sale tiếp nhận cuốc từ tài xế, kiểm tra khách và chuyển thành đề xuất điều xe nếu phù hợp.',
    driver_proposal_promoted_to_dispatch: 'Điều hành duyệt đề xuất và chuẩn bị phân xe/tài xế.',
    dispatch_proposal_approved: audience === 'sale' ? 'Sale theo dõi lệnh đã được duyệt và bổ sung thông tin nếu còn thiếu.' : 'Điều hành phân xe/tài xế cho lệnh đã duyệt.',
    dispatch_proposal_rejected: 'Sale xem lý do từ chối, chỉnh thông tin rồi gửi lại nếu cần.',
    driver_assigned: 'Tài xế mở Màn làm việc, kiểm tra chuyến, bấm Nhận chuyến và xem Google Maps.',
    driver_assignment_replaced: 'Tài xế kiểm tra lại chuyến vì xe/tài xế vừa được điều chỉnh.',
    external_driver_assigned: 'Điều hành kiểm tra xe thuê ngoài; kế toán chuẩn bị hồ sơ nhà cung cấp nếu cần.',
    supplier_profile_needed: 'Kế toán bổ sung hồ sơ nhà cung cấp thuê ngoài trước khi chốt lệnh.',
    driver_accepted_trip: 'Điều hành theo dõi chuyến đã được tài xế nhận, chờ xuất phát.',
    trip_started: 'Điều hành theo dõi chuyến đang chạy và xử lý phát sinh nếu có.',
    trip_completed: audience === 'accountant' ? 'Kế toán đối soát thu hộ, chi phí, hóa đơn và công nợ để chốt lệnh.' : 'Điều hành kiểm tra kết thúc chuyến và phát sinh vận hành.',
    driver_trip_report_submitted: 'Kế toán kiểm tra thu hộ và chi phí tài xế báo, sau đó xác nhận đối soát.'
  };
  return actions[key] || 'Mở app Angel One Ops để kiểm tra và xử lý bước tiếp theo.';
}

function formatOrderLine(order) {
  if (!order) return [];
  const route = [order.pickup, order.dropoff].filter(Boolean).join(' -> ');
  const driver = order.driver_full_name || order.external_driver_name || order.driver_id || '';
  const driverPhone = order.driver_phone || order.external_driver_phone || '';
  const vehicle = order.external_vehicle_plate_no || order.vehicle_id || '';
  const costs = [
    order.amount_due ? 'Giá bán: ' + money(order.amount_due) : '',
    order.driver_cost ? 'Giá mua/chi phí: ' + money(order.driver_cost) : ''
  ].filter(Boolean).join(' | ');
  const driverReportedCost = Number(order.driver_expense_fuel || 0) + Number(order.driver_expense_toll || 0) + Number(order.driver_expense_parking || 0) + Number(order.driver_expense_water || 0) + Number(order.driver_expense_other || 0);
  return [
    order.customer_name || order.customer_phone ? 'Khách: ' + [order.customer_name, order.customer_phone].filter(Boolean).join(' / ') : '',
    route ? 'Tuyến: ' + route : '',
    order.start_at ? 'Giờ chạy: ' + formatDateTime(order.start_at) + (order.end_at ? ' - ' + formatDateTime(order.end_at) : '') : '',
    order.service_label ? 'Dịch vụ: ' + order.service_label : '',
    vehicle || driver ? 'Xe/Tài xế: ' + [vehicle, driver, driverPhone].filter(Boolean).join(' / ') : '',
    costs,
    order.driver_collected_amount ? 'Tài xế thu hộ: ' + money(order.driver_collected_amount) : '',
    driverReportedCost ? 'Chi phí tài xế báo: ' + money(driverReportedCost) : ''
  ].filter(Boolean);
}

async function formatMessage(event) {
  const payload = event.payload || {};
  const order = await getOrder(event);
  const title = payload.title || event.event_type || 'Angel One Travel';
  const code = order?.code || payload.orderCode || payload.code || '';
  const body = payload.body || '';
  const action = actionFor(event.event_type, event.audience);
  const lines = [
    '<b>' + escapeHtml(title) + '</b>',
    'Việc cần làm: ' + escapeHtml(action),
    code ? 'Mã lệnh: <b>' + escapeHtml(code) + '</b>' : '',
    ...formatOrderLine(order).map(escapeHtml),
    !order && body ? 'Thông tin: ' + escapeHtml(body) : '',
    'Người nhận: ' + escapeHtml(event.audience),
    'Thao tác: mở Angel One Ops để xử lý.'
  ].filter(Boolean);
  return lines.join('\n');
}

async function sendTelegram(chatId, text) {
  try {
    return await httpRequest({
      method: 'POST',
      url: `https://api.telegram.org/bot${TELEGRAM_BOT_TOKEN}/sendMessage`,
      headers: { 'Content-Type': 'application/json' },
      body: { chat_id: chatId, text, parse_mode: 'HTML', disable_web_page_preview: true },
      json: true
    });
  } catch (error) {
    throw new Error(`telegram failed: ${error.message}`);
  }
}

const claimed = await supabaseRpc('claim_pending_integration_events', { p_limit: 10 });
const events = Array.isArray(claimed) ? claimed : [];
const results = [];
const deliveryGroups = new Map();

for (const event of events) {
  const chatId = chatByAudience[event.audience] || chatByAudience.admin;
  const text = await formatMessage(event);
  const payload = event.payload || {};
  const fingerprint = [
    event.event_type || '',
    event.entity_id || payload.entityId || '',
    payload.title || '',
    payload.body || ''
  ].join('::');
  const key = `${chatId}::${fingerprint}`;
  const group = deliveryGroups.get(key) || { chatId, text, events: [] };
  group.events.push(event);
  deliveryGroups.set(key, group);
}

for (const group of deliveryGroups.values()) {
  try {
    await sendTelegram(group.chatId, group.text);
    for (const event of group.events) {
      await supabaseRpc('mark_integration_event_sent', { p_event_id: event.id });
      results.push({ id: event.id, event_type: event.event_type, audience: event.audience, status: 'sent' });
    }
  } catch (error) {
    for (const event of group.events) {
      await supabaseRpc('mark_integration_event_failed', { p_event_id: event.id, p_error: error.message });
      results.push({ id: event.id, event_type: event.event_type, audience: event.audience, status: 'failed', error: error.message });
    }
  }
}

return [{ json: { claimed: events.length, sentMessages: deliveryGroups.size, results } }];
